	"com/nbx/managerapp/i18n/i18n.properties":'# This is the resource bundle for com.nbx.managerapp\n\n#Texts for manifest.json\n\n#XTIT: Application name\nappTitle=Manager System\n\n#YDES: Application description\nappDescription=An SAP Fiori application.\n#MAIN VIEW\nMainTitle = Manager App\nProjectsTitle2 = Projects List\nAddProject = New Project\nNoProjectsAssigned = You don\'t have projects assigned to you at the moment\nProjectName = Project\nBudget= Initial Budget\nStatus= Status\n\n#MAIN CONTROLLER\nfillAllRequiredToCreateProject = Please, fill all the required data to create a new project.\nProjectCreated = Project created successfully\ndefaulErrorOnNewProject = System error.\nOnCreateNewProjectError = An error ocurred:\n\n#DETAIL VIEW\nnextStatusButton = Advance Status of the Project\nchangeBudgetButton = Change Budget of the Project\nprojectDetailTitle = Project Control Panel\nProjectInfo = General Info\nTeamInfo = Team\nProjectNameInfo = Project Name\nStatusInfo = Status\nStatusInfo2 = Status of the project\nClientInfo = Client of this Project\nBudgetInfo = Initial Budget of the Project\nCloseDateInfo = This Project was closed at\nLoggedHoursInfo = Hours Review\nReportsInfo = Analytics\nremainingBudget = Remaining Budget\nprojectedRemainingBudget = Projected Remaining Budget\napprovedHours = Total Approved Hours\ntotalSpent = Spent Budget\nprojectedSpent = Projected Spent Budget\nManagerInfo = Manager on charge of this Project\nSentReportInfo = Report of the Project already sent to the Client\nNotClosedYet = Not closed\nassignedEmployeesTitle = Employees assigned to this project\nemployeeName = Name\nemployeeEmail = Contact Email\nemployeePosition = Position\nactions = Manage employees\naddEmployeeBtn = Assign Employee\nremoveEmployeeBtn = Remove Employee\nEmployeeRemovedSuccess = Employee removed from the project\n\nHoursPendingTitle = Hours Pending for Approval\nResolveRangeButton = Resolve by Date Range\nEmployeeTable = Employee\nDateTable = Date\nHoursTable = Hours\nStatusTable = Status\nApproveButton = Approve Hours\nRejectButton = Reject Hours\n\nResolvedHoursTableTitle = History of Resolved Hours\nRejReasonTable = Rejection Reason\n\nSpentPerPositionTitle = Spent Budget per Employee Position\nPositionName = Position\nHoursPerPosition = Total Hours\nCostPerPosition = Total Spent\n\nBudgetProjectionTitle = Budget Current State\nCurrentSpentAnalytic = Current spent budget\nTotalApprovedHoursAnalytic = Total hours approved for this project\nAverageHourlyCost = Average cost per hour for this project\nPendingToApproveValue = Pending to approve budget\nProjectedRemaining = Projected remaining budget\n\n#DETAIL CONTROLLER\nConfirmChangeStatusMsg = Are you sure that you want to advance the status of this project?\nConfirmChangeStatusTitle = Confirm Status Advance\nStatusUpdatedSuccess= Project status advanced.\nStatusUpdateError= An error ocurred, status failed to be updated.\nEmployeeAddedSuccess = Employee added to the project.\n\nHoursApprovedSuccess = Hours approved successfully.\nHoursRejectedSuccess = Hours rejected successfully.\n\nRangeResolvedSuccessfully = Successfully resolved {0} hour logs for this project.\nNotLogsToResolveOnSelectedRange = There are not hour logs to be resolved on the selected date range.\n\nNoNewBudgetError = Please enter a valid budget amount.\nBudgetUpdatedSuccess = Budget of the project updated.\nBudgetUpdateError = An error occurred while updating the budget.\n\n#CREATE PROJECT DIALOG FRAGMENT\nCreateNewProject = Create a new project\nProjectNameDialog = Project Name\nProjectNameExample = Ex: beCash\nProjectClient = Client\nInitialBudget = Project Initial Budget (\\u20ac)\nInitialBudgetExample = 25000.50 \nCreateProjectButton = Create Project\nCancelCreationButton = Cancel\n\n# EMPLOYEE DIALOG FRAGMENT\nselectEmployeeTitle=Select an employee to add to this project:\ncancelBtn=Cancel\n\n# REJECT DIALOG FRAGMENT\nRejectHoursTitle = Reject an Hour Log\nSelectRejectionReason = Select a valid reason to reject the hours:\nConfirmRejectRejectDialog = Confirm and resolve\nCancelRejectDialog = Cancel\n\n\n# DATE RANGE DIALOG FRAGMENT\nResolveByRangeTitle = Resolve Hours by Date Range\nSelectDateRange = Select a date range:\nFinalStatus = Select the new status:\nRejectionReason = Select a valid reason to reject the hours:\nConfirmRangeResolve = Confirm and resolve\nCancelRangeResolve = Cancel\n\n# CHANGE BUDGET DIALOG\nChangeBudgetTitle = Change the Budget for the development of this Project\nEnterNewBudget = Enter a new budget for the project\nConfirmChangeBudget = Confirm New Budget\nCancelChangeBudget = Cancel',
